def preencher_preco(apps, schema_editor):
    """O preço da nova categoria no dia em que cada troca foi pedida (T-122)."""
    TrocaVeiculo = apps.get_model("locacoes", "TrocaVeiculo")
    PrecoCategoria = apps.get_model("veiculos", "PrecoCategoria")
    trocas = TrocaVeiculo.objects.select_related(
        "locacao__filial", "locacao__plano_especial", "veiculo_novo"
    )
    for troca in trocas:
        locacao = troca.locacao
        dia = troca.criado_em.astimezone(ZoneInfo(locacao.filial.fuso)).date()
        preco = (
            PrecoCategoria.objects.filter(
                categoria_id=troca.veiculo_novo.categoria_id, vigente_desde__lte=dia
            )
            .order_by("-vigente_desde")
            .first()
        )
        if preco is None:
            continue
        periodo = {
            "diaria": preco.diaria_centavos,
            "semanal": preco.semanal_centavos,
            "mensal": preco.mensal_centavos,
        }[locacao.periodicidade]
        plano = locacao.plano_especial
        if plano is not None and plano.ativo and plano.regra == "preco_fixo":
            categorias = set(plano.categorias.values_list("pk", flat=True))
            if not categorias or troca.veiculo_novo.categoria_id in categorias:
                periodo = plano.preco_centavos or 0
        troca.valor_periodo_centavos = periodo
        troca.diaria_centavos = preco.diaria_centavos
        troca.caucao_centavos = preco.caucao_centavos
        troca.preco_do_dia = dia
        troca.save(
            update_fields=[
                "valor_periodo_centavos",
                "diaria_centavos",
                "caucao_centavos",
                "preco_do_dia",
            ]
        )


